649: func (s *Store) ReadFromPath(path string) (*Episode, error) {
650: 	f, err := os.Open(path)
651: 	if err != nil {
652: 		if os.IsNotExist(err) {
653: 			return nil, fmt.Errorf("%w: %s", ErrEpisodeNotFound, path)
654: 		}
655: 		return nil, err
656: 	}
657: 	defer f.Close()
658: 
659: 	dec, err := zstd.NewReader(f)
660: 	if err != nil {
661: 		return nil, fmt.Errorf("creating zstd reader for %s: %w", path, err)
662: 	}
663: 	defer dec.Close()
664: 
665: 	reader := bufio.NewReader(dec)
666: 
667: 	// Line 1: Header line
668: 	headerBytes, err := readLineBytes(reader)
669: 	if err != nil {
670: 		return nil, fmt.Errorf("reading episode header from %s: %w", path, err)
671: 	}
672: 	var header Header
673: 	if err := json.Unmarshal(headerBytes, &header); err != nil {
674: 		return nil, fmt.Errorf("unmarshaling episode header from %s: %w", path, err)
675: 	}
676: 
677: 	// Subsequent lines: Steps
678: 	var steps []harness.Step
679: 	lineNum := 1
680: 	for {
681: 		stepBytes, err := readLineBytes(reader)
682: 		if err != nil {
683: 			if errors.Is(err, io.EOF) {
684: 				break
685: 			}
686: 			return nil, fmt.Errorf("reading step at line %d from %s: %w", lineNum+1, path, err)
687: 		}
688: 		lineNum++
689: 		if len(stepBytes) == 0 {
690: 			continue
691: 		}
692: 		var step harness.Step
693: 		if err := json.Unmarshal(stepBytes, &step); err != nil {
694: 			return nil, fmt.Errorf("unmarshaling step at line %d from %s: %w", lineNum, path, err)
695: 		}
696: 		steps = append(steps, step)
697: 	}
698: 
699: 	return &Episode{
