409: func parseGitLogOutput(output, source string, since, until time.Time, margin time.Duration) []CandidateCommit {
410: 	var candidates []CandidateCommit
411: 	lines := strings.Split(output, "\n")
412: 	for _, line := range lines {
413: 		line = strings.TrimSpace(line)
414: 		if line == "" {
415: 			continue
416: 		}
417: 		parts := strings.Split(line, "\x1f")
418: 		if len(parts) < 4 {
419: 			continue
420: 		}
421: 		hash := strings.TrimSpace(parts[0])
422: 		shortHash := strings.TrimSpace(parts[1])
423: 		timeStr := strings.TrimSpace(parts[2])
424: 		subject := strings.TrimSpace(parts[3])
425: 
426: 		ts, _ := time.Parse(time.RFC3339, timeStr)
427: 		if ts.IsZero() {
428: 			ts, _ = time.Parse(time.RFC3339Nano, timeStr)
429: 		}
430: 
431: 		if !since.IsZero() && !ts.IsZero() && ts.Before(since.Add(-margin)) {
432: 			continue
433: 		}
434: 		if !until.IsZero() && !ts.IsZero() && ts.After(until.Add(margin)) {
435: 			continue
436: 		}
437: 
438: 		candidates = append(candidates, CandidateCommit{
439: 			Hash:      hash,
440: 			ShortHash: shortHash,
441: 			Timestamp: ts,
442: 			Subject:   subject,
443: 			Source:    source,
444: 		})
445: 	}
446: 
447: 	// git log returns newest first; reverse so candidates are chronological (oldest first)
