115: 	dsn = fmt.Sprintf("%s%s_pragma=busy_timeout(%d)&_pragma=journal_mode(WAL)&_pragma=foreign_keys(1)", dsn, sep, busyTimeoutMs)
116: 
117: 	db, err := sql.Open("sqlite", dsn)
118: 	if err != nil {
119: 		return nil, fmt.Errorf("opening sqlite database: %w", err)
120: 	}
121: 
122: 	// Enforce WAL mode and busy_timeout explicitly on connection
123: 	if _, err := db.Exec("PRAGMA journal_mode = WAL;"); err != nil {
124: 		_ = db.Close()
125: 		return nil, fmt.Errorf("setting journal_mode to WAL: %w", err)
126: 	}
127: 	if _, err := db.Exec(fmt.Sprintf("PRAGMA busy_timeout = %d;", busyTimeoutMs)); err != nil {
128: 		_ = db.Close()
129: 		return nil, fmt.Errorf("setting busy_timeout: %w", err)
130: 	}
131: 
132: 	if err := InitSchema(db); err != nil {
133: 		_ = db.Close()
134: 		return nil, fmt.Errorf("initializing schema: %w", err)
135: 	}
136: 
137: 	store.db = db
138: 	return store, nil
139: }
