149: 		maxAttempts:          DefaultMaxAttempts,
150: 		defaultLeaseDuration: DefaultLeaseDuration,
151: 		busyTimeout:          DefaultBusyTimeout,
152: 	}
153: 	for _, opt := range opts {
154: 		opt(store)
155: 	}
156: 
157: 	if err := InitSchema(db); err != nil {
158: 		return nil, fmt.Errorf("initializing schema: %w", err)
159: 	}
160: 
161: 	return store, nil
162: }
