297: // AcquireNext selects and leases the highest-priority eligible job for execution.
298: // A job is eligible if it is queued, or failed with next_attempt_at <= now.
299: // Returns (nil, nil) if no job is currently eligible.
300: func (s *Store) AcquireNext(ctx context.Context, leaseDuration time.Duration, kinds ...Kind) (*Job, error) {
301: 	if leaseDuration <= 0 {
302: 		leaseDuration = s.defaultLeaseDuration
303: 	}
304: 
305: 	tx, err := s.db.BeginTx(ctx, nil)
306: 	if err != nil {
307: 		return nil, fmt.Errorf("beginning transaction: %w", err)
308: 	}
309: 	defer func() {
310: 		_ = tx.Rollback()
311: 	}()
312: 
313: 	now := time.Now().UTC()
314: 
315: 	var query strings.Builder
316: 	query.WriteString(`
317: SELECT id, kind, priority, idempotency_key, state, lease_expires,
318:        attempts, next_attempt_at, cost, payload, last_error, created_at, updated_at
319: FROM jobs
320: WHERE (state = 'queued' OR (state = 'failed' AND (next_attempt_at IS NULL OR next_attempt_at <= ?)))
321: `)
322: 
323: 	args := []any{now}
324: 
325: 	if len(kinds) > 0 {
326: 		placeholders := make([]string, len(kinds))
327: 		for i, k := range kinds {
328: 			placeholders[i] = "?"
329: 			args = append(args, string(k))
330: 		}
331: 		query.WriteString(fmt.Sprintf(" AND kind IN (%s)", strings.Join(placeholders, ", ")))
332: 	}
333: 
334: 	query.WriteString(" ORDER BY priority DESC, created_at ASC LIMIT 1;")
335: 
336: 	row := tx.QueryRowContext(ctx, query.String(), args...)
337: 	job, err := scanJob(row)
338: 	if err != nil {
339: 		if errors.Is(err, sql.ErrNoRows) {
340: 			return nil, nil // No jobs available
341: 		}
342: 		return nil, fmt.Errorf("querying eligible job: %w", err)
343: 	}
344: 
345: 	if err := ValidateTransition(job.State, StateRunning); err != nil {
346: 		return nil, fmt.Errorf("acquiring job %s: %w", job.ID, err)
347: 	}
348: 
349: 	leaseExpires := now.Add(leaseDuration)
350: 	attempts := job.Attempts + 1
351: 
352: 	updateQuery := `
353: UPDATE jobs
354: SET state = ?, attempts = ?, lease_expires = ?, next_attempt_at = NULL, updated_at = ?
355: WHERE id = ? AND state = ?;
356: `
357: 	res, err := tx.ExecContext(ctx, updateQuery,
358: 		string(StateRunning),
359: 		attempts,
360: 		leaseExpires,
361: 		now,
362: 		job.ID,
363: 		string(job.State),
364: 	)
365: 	if err != nil {
366: 		return nil, fmt.Errorf("updating job to running: %w", err)
367: 	}
368: 
369: 	rows, err := res.RowsAffected()
370: 	if err != nil {
371: 		return nil, fmt.Errorf("checking rows affected: %w", err)
372: 	}
373: 	if rows == 0 {
374: 		// Concurrently acquired
375: 		return nil, nil
376: 	}
377: 
378: 	if err := tx.Commit(); err != nil {
379: 		return nil, fmt.Errorf("committing acquire transaction: %w", err)
380: 	}
381: 
382: 	job.State = StateRunning
383: 	job.Attempts = attempts
384: 	job.LeaseExpires = &leaseExpires
385: 	job.NextAttemptAt = nil
386: 	job.UpdatedAt = now
387: 
388: 	return job, nil
389: }
