391: // RenewLease extends the lease duration of a currently running job.
392: func (s *Store) RenewLease(ctx context.Context, id string, leaseDuration time.Duration) error {
393: 	if id == "" {
394: 		return fmt.Errorf("%w: id cannot be empty", ErrInvalidJob)
395: 	}
396: 	if leaseDuration <= 0 {
397: 		leaseDuration = s.defaultLeaseDuration
398: 	}
399: 
400: 	now := time.Now().UTC()
401: 	leaseExpires := now.Add(leaseDuration)
402: 
403: 	query := `
404: UPDATE jobs
405: SET lease_expires = ?, updated_at = ?
406: WHERE id = ? AND state = 'running';
407: `
408: 	res, err := s.db.ExecContext(ctx, query, leaseExpires, now, id)
409: 	if err != nil {
410: 		return fmt.Errorf("renewing lease for %s: %w", id, err)
411: 	}
412: 
413: 	rows, err := res.RowsAffected()
414: 	if err != nil {
415: 		return fmt.Errorf("checking rows affected: %w", err)
416: 	}
417: 	if rows == 0 {
418: 		job, err := s.Get(ctx, id)
419: 		if err != nil {
420: 			return err
421: 		}
422: 		if job.State != StateRunning {
423: 			return fmt.Errorf("%w: job is in state %q, not running", ErrInvalidTransition, job.State)
424: 		}
425: 		return ErrLeaseExpired
426: 	}
427: 
428: 	return nil
429: }
