438: 	if err != nil {
439: 		return err
440: 	}
441: 
442: 	if err := ValidateTransition(job.State, StateDone); err != nil {
443: 		return fmt.Errorf("completing job %s: %w", id, err)
444: 	}
445: 
446: 	now := time.Now().UTC()
447: 	query := `
448: UPDATE jobs
449: SET state = ?, cost = ?, lease_expires = NULL, updated_at = ?
450: WHERE id = ?;
451: `
452: 	_, err = s.db.ExecContext(ctx, query, string(StateDone), costValue(cost), now, id)
453: 	if err != nil {
454: 		return fmt.Errorf("marking job %s done: %w", id, err)
455: 	}
456: 
457: 	return nil
