689: // Stats returns counts of jobs grouped by state.
690: func (s *Store) Stats(ctx context.Context) (Stats, error) {
691: 	query := "SELECT state, COUNT(*) FROM jobs GROUP BY state;"
692: 	rows, err := s.db.QueryContext(ctx, query)
693: 	if err != nil {
694: 		return Stats{}, fmt.Errorf("querying stats: %w", err)
695: 	}
696: 	defer rows.Close()
697: 
698: 	var stats Stats
699: 	for rows.Next() {
700: 		var stateStr string
701: 		var count int
702: 		if err := rows.Scan(&stateStr, &count); err != nil {
703: 			return Stats{}, fmt.Errorf("scanning stats row: %w", err)
704: 		}
705: 		stats.Total += count
706: 		switch State(stateStr) {
707: 		case StateQueued:
708: 			stats.Queued = count
709: 		case StateRunning:
710: 			stats.Running = count
711: 		case StateDone:
712: 			stats.Done = count
713: 		case StateFailed:
714: 			stats.Failed = count
715: 		case StateDead:
716: 			stats.Dead = count
717: 		case StateSubmitted:
718: 			stats.Submitted = count
719: 		}
720: 	}
721: 
722: 	return stats, rows.Err()
723: }
724: 
725: func scanJob(scanner interface{ Scan(dest ...any) error }) (*Job, error) {
726: 	var j Job
727: 	var kindStr, stateStr string
728: 	var idempotencyKey, costStr, payload, lastError sql.NullString
729: 	var leaseExpires, nextAttemptAt sql.NullTime
730: 
731: 	err := scanner.Scan(
732: 		&j.ID,
733: 		&kindStr,
734: 		&j.Priority,
